def run_hardware_vectors(fn, mode, run_case):
    """Pass independent hardware outputs into the existing native fixture."""
    for lhs, rhs, dest, lo0, hi0, lo1, hi1 in VECTORS.get(mode, ()):
        run_case(fn, mode, (*INITIAL_BANKS, lhs, rhs),
                 (dest, [lo0, hi0, lo1, hi1]))
    return len(VECTORS.get(mode, ()))
